                default:begin end
            endcase
        end else if(i_y >= 112 && i_y < 126 && i_x >= 192 && i_x < 1264)begin
            flag_text=1;glyph_row=(i_y-112) >> 1;character_column=(i_x-192) >> 4;
            if(character_column < 15)begin
                dec_ink=24'hff4050;
                case(character_column)
                    0:dec_character=82;1:dec_character=69;2:dec_character=68;
                    default:if(character_column >= 4 && character_column < 14)dec_character=48+i_red_bcd[(13-character_column)*4 +:4];
                endcase
            end else if(character_column < 32)begin
                dec_ink=24'h20ef70;local_column=character_column-15;
                case(local_column)
                    0:dec_character=71;1:dec_character=82;2:dec_character=69;3:dec_character=69;4:dec_character=78;
                    default:if(local_column >= 6 && local_column < 16)dec_character=48+i_green_bcd[(15-local_column)*4 +:4];
                endcase
            end else if(character_column < 50)begin
                dec_ink=24'hffdf20;local_column=character_column-32;
                case(local_column)
                    0:dec_character=89;1:dec_character=69;2:dec_character=76;3:dec_character=76;4:dec_character=79;5:dec_character=87;
                    default:if(local_column >= 7 && local_column < 17)dec_character=48+i_yellow_bcd[(16-local_column)*4 +:4];
                endcase
            end else begin
                local_column=character_column-50;
                case(local_column)
                    0:dec_character=84;1:dec_character=79;2:dec_character=84;3:dec_character=65;4:dec_character=76;
                    default:if(local_column >= 6 && local_column < 17)dec_character=48+i_total_bcd[(16-local_column)*4 +:4];
                endcase
            end
        end
        if(!flag_text)dec_character=32;
    end
    wire small_character_valid=dec_character[6] ^ dec_character[5];
    wire [5:0] small_index=small_character_valid ? {~dec_character[5],dec_character[4:0]} : 6'd0;
    wire [12:0] font_address=large_font ? large_address : {4'hf,small_index,glyph_row[2:0]};
    reg [12:0] reg_glyph_address;
    always @(posedge i_clk)reg_glyph_address<=font_address;
    // 同步字模行与原查询同拍；有效/面板复位遮罩未复位的ROM输出。
    always @(posedge i_clk)begin
        reg_glyph_line<=rom_glyph_lines[C_PREDECODE ? reg_glyph_address : font_address];
    end
                                                                            
    reg [95:0] query_rgb;
    reg [3:0] query_markers,query_pixel_offset;
    reg [23:0] query_ink,query_background;
    reg query_raw_group,query_raw_text,query_view,query_panel,query_logo;
    reg [1:0] query_logo_offset;
    reg [7:0] query_logo_data;
    wire [95:0] compose_rgb=C_PREDECODE ? query_rgb : reg_rgb;
    wire [3:0] compose_markers=C_PREDECODE ? query_markers : reg_markers;
    wire [3:0] compose_offset=C_PREDECODE ? query_pixel_offset : reg_pixel_offset;
    wire [23:0] compose_ink=C_PREDECODE ? query_ink : reg_ink;
    wire [23:0] compose_background=C_PREDECODE ? query_background : reg_background;
    wire compose_raw_group=C_PREDECODE ? query_raw_group : raw_group;
    wire compose_raw_text=C_PREDECODE ? query_raw_text : raw_text;
    wire compose_view=C_PREDECODE ? query_view : view_registered;
    wire compose_panel=C_PREDECODE ? query_panel : flag_panel;
    wire compose_logo=C_PREDECODE ? query_logo : flag_logo;
    wire [1:0] compose_logo_offset=C_PREDECODE ? query_logo_offset : reg_logo_offset;
    wire [7:0] compose_logo_data=C_PREDECODE ? query_logo_data : reg_logo;
    always @(posedge i_clk or negedge i_rstn)begin
        if(!i_rstn)begin
            reg_rgb<=0;reg_markers<=0;reg_pixel_offset<=0;
            reg_ink<=0;reg_background<=0;raw_group<=0;reg_logo_offset<=0;raw_text<=0;view_registered<=0;
            flag_panel<=0;flag_logo<=0;reg_rgb_o<=0;reg_markers_o<=0;
            query_rgb<=0;query_markers<=0;query_pixel_offset<=0;query_ink<=0;query_background<=0;
            query_raw_group<=0;query_raw_text<=0;query_view<=0;query_panel<=0;query_logo<=0;
            query_logo_offset<=0;query_logo_data<=0;
        end else begin
            reg_rgb<=i_rgb;reg_markers<={i_valid,i_sof,i_eol,i_eof};
            reg_pixel_offset<=i_x[3:0];
            reg_ink<=dec_ink;reg_background<=dec_background;
            view_registered<=ball_header;raw_group<=raw_tx[2];
            reg_logo_offset<=C_SCALAR_RENDER ? i_x[1:0] : 2'd0;raw_text<=raw_tx<384 && raw_ty<64;
            flag_panel<=ball_header ? i_y<144 : (i_x>=848 && i_x<1264 && i_y>=16 && i_y<96);
            flag_logo<=i_x >= (ball_header ? 24 : 16) && i_x < (ball_header ? 152 : 144) && i_y >= 16 && i_y < 96;
            query_rgb<=reg_rgb;query_markers<=reg_markers;query_pixel_offset<=reg_pixel_offset;
            query_ink<=reg_ink;query_background<=reg_background;query_raw_group<=raw_group;
            query_raw_text<=raw_text;query_view<=view_registered;query_panel<=flag_panel;query_logo<=flag_logo;
            query_logo_offset<=reg_logo_offset;query_logo_data<=reg_logo;
            reg_markers_o<=compose_markers;
            if(C_SCALAR_RENDER)reg_rgb_o[71:0]<=72'd0;
            for(lane=0;lane<(C_SCALAR_RENDER ? 1 : 4);lane=lane+1)begin
                pixel=compose_panel ? (compose_view ? compose_background : 24'h101820) : compose_rgb[95-lane*24 -:24];
                pixel_column=(compose_offset+lane) >> 1;
                if(compose_view)begin
                    if(compose_panel && pixel_column < 5 && reg_glyph_line[4-pixel_column])pixel=compose_ink;
                end else if(compose_panel && compose_raw_text && reg_glyph_line[7-({compose_raw_group,2'b00}+compose_logo_offset+lane)])pixel=24'hFFE066;
                if(compose_logo)pixel=logo_color(compose_logo_data[7-(compose_logo_offset+lane)*2 -:2]);
                reg_rgb_o[95-lane*24 -:24]<=pixel;
            end
        end
    end
    assign o_rgb=reg_rgb_o;
    assign o_valid=reg_markers_o[3];
    assign o_sof=reg_markers_o[2];
    assign o_eol=reg_markers_o[1];
    assign o_eof=reg_markers_o[0];
endmodule
